import React, { useState, useEffect, useMemo, useRef } from 'react'
import AdaptableCard from 'components/shared/AdaptableCard'
import DataTable from 'components/shared/DataTable'
import debounce from 'lodash/debounce'
import Button from 'components/ui/Buttons'
import Input from 'components/ui/Input'
import { MdCreate, MdAdd, MdImportExport } from 'react-icons/md'
import { Link, useNavigate } from 'react-router-dom'
import { HiSearch } from 'react-icons/hi'
import { exportToExcel } from 'react-easy-export'
import { apiRawMaterialQtyInGet } from 'services/RawMaterialQtyInService'
import NumberFormat from 'react-number-format'

const RawMaterialQtyIn = () => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(false)
    const [selectedRows, setSelectedRows] = useState([])
    const [tableData, setTableData] = useState({
        total: 0,
        pageIndex: 1,
        pageSize: 10,
        query: '',
        sort: {
            order: '',
            key: '',
        },
    })
    const navigate = useNavigate()
    const inputRef = useRef(null)

    const debounceFn = debounce(handleDebounceFn, 1000)

    function handleDebounceFn(val) {
        if (typeof val === 'string' && (val.length > 1 || val.length === 0)) {
            setTableData((prevData) => ({
                ...prevData,
                ...{ query: val, pageIndex: 1 },
            }))
        }
    }

    const handleChange = (e) => {
        debounceFn(e.target.value)
    }

    const handleRowClick = (dataid) => {
        navigate(
            `/transaction/raw-material-qty-in/edit-raw-material-qty-in/${dataid}`
        )
    }

    const columns = useMemo(
        () => [
            {
                header: 'Date Of Receipt',
                accessorKey: 'date_of_receipt',
                cell: (props) => {
                    let a = new Date(props.row.original.date_of_receipt)
                    return `${
                        a.getDate() < 10 ? '0' + a.getDate() : a.getDate()
                    }-${
                        a.getMonth() < 10
                            ? '0' + (a.getMonth() + 1)
                            : a.getMonth() + 1
                    }-${a.getFullYear()}`
                },
                width: 100,
            },
            {
                header: 'PO No.',
                cell: (props) => {
                    return props.row.original.purchase_order === null ||
                        props.row.original.purchase_order === ''
                        ? ''
                        : props.row.original.purchase_order['po_no']
                },
                width: 180,
            },
            {
                header: 'Vendor Name',
                cell: (props) => {
                    return props.row.original.vendor === null ||
                        props.row.original.vendor === ''
                        ? ''
                        : props.row.original.vendor['vendor_name']
                },
            },
            {
                header: 'Depot Name',
                cell: (props) => {
                    return props.row.original.depot === null ||
                        props.row.original.depot === ''
                        ? ''
                        : props.row.original.depot['depot_name']
                },
            },
            {
                header: 'Amount',
                cell: (props) => {
                    return props.row.original.final_amount === null ||
                        props.row.original.final_amount === '' ? (
                        ''
                    ) : (
                        <NumberFormat
                            displayType="text"
                            prefix={'₹'}
                            thousandsGroupStyle={'lakh'}
                            decimalScale={2}
                            value={props.row.original.final_amount}
                            allowLeadingZeros
                            thousandSeparator=","
                        />
                    )
                },
                width: 100,
            },
            {
                header: 'Status',
                accessorKey: 'status',
                width: 90,
            },
            {
                header: 'Action',
                width: 70,
                cell: (props) => (
                    <>
                        <Button
                            shape="circle"
                            size="sm"
                            variant="twoTone"
                            icon={<MdCreate />}
                            className="mr-3"
                            onClick={() => {
                                handleRowClick(props.row.original.id)
                            }}
                        />
                    </>
                ),
            },
        ],
        []
    )

    const handlePaginationChange = (pageIndex) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageIndex } }))
    }

    const handleSelectChange = (pageSize) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageSize } }))
    }

    const handleSort = ({ order, key }) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ sort: { order, key } },
        }))
    }

    const handleRowSelect = (checked, row) => {
        console.log('row', row)
        if (checked) {
            setSelectedRows((prevData) => {
                if (!prevData.includes(row)) {
                    return [...prevData, ...[row]]
                }
                return prevData
            })
        } else {
            setSelectedRows((prevData) => {
                if (prevData.includes(row)) {
                    return prevData.filter((prevRow) => prevRow.id !== row.id)
                }
                return prevData
            })
        }
    }

    const handleAllRowSelect = (checked, rows) => {
        console.log('rows', rows)
        if (checked) {
            const originalRows = rows.map((row) => row.original)
            const selectedIds = []
            originalRows.forEach((row) => {
                selectedIds.push(row)
            })
            setSelectedRows(selectedIds)
        } else {
            setSelectedRows([])
        }
    }
    console.log('RawMaterialQtyIn.js Loading....')
    useEffect(() => {
        const fetchData = async () => {
            setLoading(true)
            const data = await apiRawMaterialQtyInGet(tableData)
            if (data.data) {
                console.log(data.data)
                setData(data.data['rows'])
                setLoading(false)
                setTableData((prevData) => ({
                    ...prevData,
                    ...{ total: data.data['total'] },
                }))
            }
        }
        fetchData()
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        tableData.pageIndex,
        tableData.sort,
        tableData.pageSize,
        tableData.query,
    ])
    return (
        <AdaptableCard className="card-shadow">
            <div className="lg:flex items-center justify-between mb-2">
                <h3 className="mb-4 lg:mb-0 ">Raw Material Qty In</h3>
                <div className="flex flex-row lg:flex-row lg:items-center">
                    <Input
                        ref={inputRef}
                        placeholder="Search..."
                        size="sm"
                        className="lg:w-52 mr-4"
                        onChange={handleChange}
                        prefix={<HiSearch className="text-lg" />}
                    />
                    <Link
                        to={
                            '/transaction/raw-material-qty-in/add-raw-material-qty-in'
                        }
                        className=" mr-4 inline-flex"
                    >
                        <Button size="sm" variant="solid" icon={<MdAdd />}>
                            <span>Add Raw Material Qty In</span>
                        </Button>
                    </Link>
                    <div className=" inline-flex">
                        <Button
                            size="sm"
                            variant="solid"
                            color="emerald-600"
                            icon={<MdImportExport />}
                            onClick={() => {
                                exportToExcel(selectedRows)
                            }}
                            disabled={!selectedRows.length > 0}
                        >
                            <span>Download</span>
                        </Button>
                    </div>
                </div>
            </div>
            {/* {selectedRows.length > 0 && (
                <div className="flex justify-end mb-4">
                    <Button
                        size="sm"
                        variant="solid"
                        onClick={handleBatchAction}
                    >
                        Batch Action
                    </Button>
                </div>
            )} */}

            <DataTable
                selectable
                columns={columns}
                data={data}
                loading={loading}
                pagingData={tableData}
                onPaginationChange={handlePaginationChange}
                onSelectChange={handleSelectChange}
                onSort={handleSort}
                onCheckBoxChange={handleRowSelect}
                onIndeterminateCheckBoxChange={handleAllRowSelect}
                columnShow={+true}
            />
        </AdaptableCard>
    )
}

export default RawMaterialQtyIn
